import { Webhook } from "standardwebhooks";

// Fixture only; never use this secret outside automated tests.
export const DODO_FIXTURE_SECRET =
  "whsec_" +
  Buffer.from("fixture-webhook-signing-key-with-32-bytes").toString("base64");
export function signedDodoHeaders(
  raw: string,
  webhookId = "evt_fixture",
  seconds = Math.floor(Date.now() / 1000),
  secret = DODO_FIXTURE_SECRET,
) {
  return {
    "webhook-id": webhookId,
    "webhook-timestamp": String(seconds),
    "webhook-signature": new Webhook(secret).sign(
      webhookId,
      new Date(seconds * 1000),
      raw,
    ),
  };
}
